window.READING_TESTS[2]={"id": 2, "module": "reading", "vol": 9, "sections": [{"number": 1, "html": "<p class=\"subheading\"><b>Questions 1–7</b></p><p class=\"instruction\">Complete the notes below.</p><p class=\"instruction\">Write <b>ONE WORD ONLY</b> from the passage for each answer. </p><p class=\"\"><b>Carnegie’s Life</b></p><p><i><b>1835-1855  </b></i>•   found employment in the same workplace as his <span class=\"qnum\">1</span><input class=\"gap\" data-q=\"1\" aria-label=\"Câu 1\" autocomplete=\"off\" spellcheck=\"false\">•   educated himself through books, theatrical performances and <span class=\"qnum\">2</span><input class=\"gap\" data-q=\"2\" aria-label=\"Câu 2\" autocomplete=\"off\" spellcheck=\"false\"></p><p><i><b>1855-1865 </b></i>•    worked in a telegraph office •    became <span class=\"qnum\">3</span><input class=\"gap\" data-q=\"3\" aria-label=\"Câu 3\" autocomplete=\"off\" spellcheck=\"false\"> to Thomas A Scott at Pennsylvania Railroad </p><p><i><b>1865-1870 </b></i>•    made investments in the US and England •    realised that changing engineering needs would require a greater demand for <span class=\"qnum\">4</span><input class=\"gap\" data-q=\"4\" aria-label=\"Câu 4\" autocomplete=\"off\" spellcheck=\"false\"></p><p><i><b>1873 </b></i>•    managed a rail manufacturing business by: +   reducing <span class=\"qnum\">5</span><input class=\"gap\" data-q=\"5\" aria-label=\"Câu 5\" autocomplete=\"off\" spellcheck=\"false\">+   restructuring +   reinvesting profit and sometimes borrowing money from <span class=\"qnum\">6</span><input class=\"gap\" data-q=\"6\" aria-label=\"Câu 6\" autocomplete=\"off\" spellcheck=\"false\"></p><p><i><b>1880s</b></i> •    Frick and Carnegie became partners •    Carnegie’s responsibilities: +   arranging future <span class=\"qnum\">7</span><input class=\"gap\" data-q=\"7\" aria-label=\"Câu 7\" autocomplete=\"off\" spellcheck=\"false\"> and innovations for factories •    Frick&#x27;s responsibilities: Production</p>\n<p class=\"subheading\"><b>Questions 8–13</b></p><p class=\"instruction\">Choose<b> TRUE</b> if the statement agrees with the information given in the text, choose <b>FALSE</b> if the statement contradicts the information, or choose <b>NOT GIVEN</b> if there is no information on this.</p><div data-render-choice=\"8\"></div><div data-render-choice=\"9\"></div><div data-render-choice=\"10\"></div><div data-render-choice=\"11\"></div><div data-render-choice=\"12\"></div><div data-render-choice=\"13\"></div>"}, {"number": 2, "html": "<p class=\"subheading\"><b>Questions 14–15</b></p><p class=\"instruction\">Reading Passage 3 has eight paragraphs, <b>A-H</b>.</p><p class=\"instruction\"><i>Which paragraph contains the following information?</i></p><p class=\"instruction\">Choose the correct letter, <b>A-H</b>, in boxes <b>14-15</b>.</p><div class=\"bank\"><button class=\"token\" draggable=\"true\" data-token=\"A\"><b>A</b> A</button><button class=\"token\" draggable=\"true\" data-token=\"B\"><b>B</b> B</button><button class=\"token\" draggable=\"true\" data-token=\"C\"><b>C</b> C</button><button class=\"token\" draggable=\"true\" data-token=\"D\"><b>D</b> D</button><button class=\"token\" draggable=\"true\" data-token=\"E\"><b>E</b> E</button><button class=\"token\" draggable=\"true\" data-token=\"F\"><b>F</b> F</button><button class=\"token\" draggable=\"true\" data-token=\"G\"><b>G</b> G</button><button class=\"token\" draggable=\"true\" data-token=\"H\"><b>H</b> H</button></div><p class=\"matching-row\" data-drop=\"14\"><span class=\"qnum\">14</span>the effect that a client&#x27;s requirements have on the nature of a translation. <select class=\"answer-select\" data-q=\"14\" aria-label=\"Câu 14\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option><option value=\"H\">H · H</option></select></p><p class=\"matching-row\" data-drop=\"15\"><span class=\"qnum\">15</span>contrasting attitudes towards translators. <select class=\"answer-select\" data-q=\"15\" aria-label=\"Câu 15\"><option value=\"\">Chọn</option><option value=\"A\">A · A</option><option value=\"B\">B · B</option><option value=\"C\">C · C</option><option value=\"D\">D · D</option><option value=\"E\">E · E</option><option value=\"F\">F · F</option><option value=\"G\">G · G</option><option value=\"H\">H · H</option></select></p>\n<p class=\"subheading\"><b>Questions 16–19</b></p><p class=\"instruction\">Complete the summary below.</p><p class=\"instruction\">Write <b>NO MORE THAN TWO WORDS</b> from paragraphs C, D and E for each answer. </p><p class=\"\"><b>The goal of translation</b></p><p>Translation is an attempt to create a text in the target language which displays <span class=\"qnum\">16</span><input class=\"gap\" data-q=\"16\" aria-label=\"Câu 16\" autocomplete=\"off\" spellcheck=\"false\"> with a source text It is inevitable that not all information can be conveyed, however, so translations are best judged according to their <span class=\"qnum\">17</span><input class=\"gap\" data-q=\"17\" aria-label=\"Câu 17\" autocomplete=\"off\" spellcheck=\"false\">, for example, the translator of a business letter or scientific text does not need to consider its <span class=\"qnum\">18</span><input class=\"gap\" data-q=\"18\" aria-label=\"Câu 18\" autocomplete=\"off\" spellcheck=\"false\"> aspects while someone dubbing a film may give a relatively low value to <span class=\"qnum\">19</span><input class=\"gap\" data-q=\"19\" aria-label=\"Câu 19\" autocomplete=\"off\" spellcheck=\"false\"></p>\n<p class=\"subheading\"><b>Questions 20–23</b></p><p class=\"instruction\">Look at the following features of translating and the types of translation below.</p><p class=\"instruction\">Match each feature with the correct type of translation, <b>A-F</b>.</p><p class=\"instruction\">Choose the correct letter, <b>A-F</b>, in boxes <b>20-23</b>.</p><p class=\"instruction\"><b>Types of Translation</b></p><p class=\"instruction\"><b>A</b>       aesthetic<b>B </b>      ethnographic<b>C </b>      free<b>D</b>       literal<b>E</b>       pragmatic<b>F</b>       word-for-word</p><div class=\"bank\"><button class=\"token\" draggable=\"true\" data-token=\"A\"><b>A</b> aesthetic</button><button class=\"token\" draggable=\"true\" data-token=\"B\"><b>B</b> ethnographic</button><button class=\"token\" draggable=\"true\" data-token=\"C\"><b>C</b> free</button><button class=\"token\" draggable=\"true\" data-token=\"D\"><b>D</b> literal</button><button class=\"token\" draggable=\"true\" data-token=\"E\"><b>E</b> pragmatic</button><button class=\"token\" draggable=\"true\" data-token=\"F\"><b>F</b> word-for-word</button></div><p class=\"matching-row\" data-drop=\"20\"><span class=\"qnum\">20</span>focuses on reproducing the content accurately. <select class=\"answer-select\" data-q=\"20\" aria-label=\"Câu 20\"><option value=\"\">Chọn</option><option value=\"A\">A · aesthetic</option><option value=\"B\">B · ethnographic</option><option value=\"C\">C · free</option><option value=\"D\">D · literal</option><option value=\"E\">E · pragmatic</option><option value=\"F\">F · word-for-word</option></select></p><p class=\"matching-row\" data-drop=\"21\"><span class=\"qnum\">21</span>looks at important cultural aspects of language use. <select class=\"answer-select\" data-q=\"21\" aria-label=\"Câu 21\"><option value=\"\">Chọn</option><option value=\"A\">A · aesthetic</option><option value=\"B\">B · ethnographic</option><option value=\"C\">C · free</option><option value=\"D\">D · literal</option><option value=\"E\">E · pragmatic</option><option value=\"F\">F · word-for-word</option></select></p><p class=\"matching-row\" data-drop=\"22\"><span class=\"qnum\">22</span>follows the original grammatical structures as required by the target language. <select class=\"answer-select\" data-q=\"22\" aria-label=\"Câu 22\"><option value=\"\">Chọn</option><option value=\"A\">A · aesthetic</option><option value=\"B\">B · ethnographic</option><option value=\"C\">C · free</option><option value=\"D\">D · literal</option><option value=\"E\">E · pragmatic</option><option value=\"F\">F · word-for-word</option></select></p><p class=\"matching-row\" data-drop=\"23\"><span class=\"qnum\">23</span>focuses on meaning without necessarily using the original grammatical structures. <select class=\"answer-select\" data-q=\"23\" aria-label=\"Câu 23\"><option value=\"\">Chọn</option><option value=\"A\">A · aesthetic</option><option value=\"B\">B · ethnographic</option><option value=\"C\">C · free</option><option value=\"D\">D · literal</option><option value=\"E\">E · pragmatic</option><option value=\"F\">F · word-for-word</option></select></p>\n<p class=\"subheading\"><b>Questions 24–26</b></p><p class=\"instruction\">Choose <b>THREE</b> correct answers.</p><div data-render-pair=\"24\"></div>"}, {"number": 3, "html": "<p class=\"subheading\"><b>Questions 27–30</b></p><p class=\"instruction\">Complete the summary using the list of words and phrases, <b>A-D</b>, below.</p><p class=\"\"><b>A poverty    B agriculture    C boats     D wood</b></p><p class=\"\"><b>Early European reaction to the discovery of Easter Island</b></p><p>When Dutchman Jacob Roggeveen sailed to Easter Island in 1722, he was amazed by the stone statues he saw for a number of reasons. Firstly, it was clear that they were immensely heavy, and there was no <span class=\"inline-match\" data-drop=\"27\"><span class=\"qnum\">27</span><select class=\"answer-select\" data-q=\"27\" aria-label=\"Câu 27\"><option value=\"\">Chọn</option><option value=\"A\">A · poverty</option><option value=\"B\">B · agriculture</option><option value=\"C\">C · boats</option><option value=\"D\">D · wood</option></select></span> around, which would have helped with their construction. Roggeveen did not think the inhabitants had any metal tools, or animals for heavy labour either. Another mystery was the poor quality of the local inhabitants&#x27; <span class=\"inline-match\" data-drop=\"28\"><span class=\"qnum\">28</span><select class=\"answer-select\" data-q=\"28\" aria-label=\"Câu 28\"><option value=\"\">Chọn</option><option value=\"A\">A · poverty</option><option value=\"B\">B · agriculture</option><option value=\"C\">C · boats</option><option value=\"D\">D · wood</option></select></span>; Roggeveen wondered how the people had managed to survive long trips. At the time of Roggeveen&#x27;s visit, he observed that the people were living in <span class=\"inline-match\" data-drop=\"29\"><span class=\"qnum\">29</span><select class=\"answer-select\" data-q=\"29\" aria-label=\"Câu 29\"><option value=\"\">Chọn</option><option value=\"A\">A · poverty</option><option value=\"B\">B · agriculture</option><option value=\"C\">C · boats</option><option value=\"D\">D · wood</option></select></span> and there was no evidence of successful <span class=\"inline-match\" data-drop=\"30\"><span class=\"qnum\">30</span><select class=\"answer-select\" data-q=\"30\" aria-label=\"Câu 30\"><option value=\"\">Chọn</option><option value=\"A\">A · poverty</option><option value=\"B\">B · agriculture</option><option value=\"C\">C · boats</option><option value=\"D\">D · wood</option></select></span> on the island.</p>\n<p class=\"subheading\"><b>Questions 31–35</b></p><p class=\"instruction\">Choose <b>YES </b>if the statement agrees with the claims of the writer, choose <b>NO</b> if the statement contradicts the claims of the writer, or <b>NOT GIVEN</b> if it is impossible to say what the writer thinks about this.</p><div data-render-choice=\"31\"></div><div data-render-choice=\"32\"></div><div data-render-choice=\"33\"></div><div data-render-choice=\"34\"></div><div data-render-choice=\"35\"></div>\n<p class=\"subheading\"><b>Questions 36–40</b></p><p class=\"instruction\">Choose the correct answer.</p><div data-render-choice=\"36\"></div><div data-render-choice=\"37\"></div><div data-render-choice=\"38\"></div><div data-render-choice=\"39\"></div><div data-render-choice=\"40\"></div>"}], "passages": [{"number": 1, "title": "Andrew Carnegie: industrialist and philanthropist", "subtitle": ""}, {"number": 2, "title": "Translating: a key to international understanding?", "subtitle": ""}, {"number": 3, "title": "The mystery of Easter Island", "subtitle": "<i>What could possibly explain the lack of vegetation on Easter Island?</i>"}], "singles": [{"n": 8, "prompt": "Carnegie believed that the USA offered more opportunities than European countries did.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 9, "prompt": "A smaller workforce was required at the Homestead factory after Carnegie took control.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 10, "prompt": "Carnegie prevented his workers from joining unions.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 11, "prompt": "Carnegie blamed Frick for the violent workers strike in 1892.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 12, "prompt": "In the 1890s Carnegie negotiated with his competitors.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 13, "prompt": "Carriage’s provision of funds for libraries was limited to those in the United States.", "options": ["TRUE", "FALSE", "NOT GIVEN"], "values": ["TRUE", "FALSE", "NOT GIVEN"]}, {"n": 31, "prompt": "Erich von Däniken's claims were briefly accepted by some sections of society.", "options": ["YES", "NO", "NOT GIVEN"], "values": ["YES", "NO", "NOT GIVEN"]}, {"n": 32, "prompt": "Archaeologists removed valuable artefacts from the island.", "options": ["YES", "NO", "NOT GIVEN"], "values": ["YES", "NO", "NOT GIVEN"]}, {"n": 33, "prompt": "Smallpox continued to affect Easter Island's inhabitants for centuries.", "options": ["YES", "NO", "NOT GIVEN"], "values": ["YES", "NO", "NOT GIVEN"]}, {"n": 34, "prompt": "It remains open to question whether Easter Island was once covered in forest.", "options": ["YES", "NO", "NOT GIVEN"], "values": ["YES", "NO", "NOT GIVEN"]}, {"n": 35, "prompt": "The way that rats arrived on Easter Island is still to be established.", "options": ["YES", "NO", "NOT GIVEN"], "values": ["YES", "NO", "NOT GIVEN"]}, {"n": 36, "prompt": "What does Jared Diamond blame for the lack of vegetation on Easter Island?", "options": ["The construction of stone statues", "Climate change over a long period", "A method of transportation", "The arrival of Europeans"]}, {"n": 37, "prompt": "What do Hunt and Lipo suggest about the population of Easter Island?", "options": ["It collapsed before European contact", "The first settlers arrived much later than is widely accepted", "It never exceeded a few thousand inhabitants", "It declined mainly because of disease"]}, {"n": 38, "prompt": "What is suggested about rats on Easter Island in the fifth paragraph?", "options": ["They were a likely cause of deforestation", "They arrived after the forests had disappeared", "They had no effect on plant regeneration", "They were introduced by Europeans"]}, {"n": 39, "prompt": "Flenley responds to Hunt and Lipo’s theory by", "options": ["dismissing it", "partially supporting it", "expanding on their arguments", "avoiding direct criticism"]}, {"n": 40, "prompt": "The writer’s purpose in this article is to", "options": ["argue in favour of Diamond’s interpretation", "provide an overview of a series of arguments", "prove that rats were the main cause of deforestation", "criticise modern archaeological methods"]}], "pairs": [{"n": 24, "size": 3, "prompt": "Which THREE of the following points are mentioned by the writer of the passage?", "options": ["The objectives of translating are always clearly different from those of interpreting.", "A translator may need to consider the culture of the target language.", "Translation is an activity which requires professional training.", "It is difficult to specify what constitutes a very good translation.", "The skill required for translation is increasingly gaining recognition.", "A translation should give the impression of being an original work."]}], "answers": {"1": ["father"], "2": ["music"], "3": ["secretary"], "4": ["steel"], "5": ["prices"], "6": ["banks"], "7": ["projects"], "8": ["TRUE"], "9": ["TRUE"], "10": ["FALSE"], "11": ["NOT GIVEN"], "12": ["FALSE"], "13": ["FALSE"], "14": ["E"], "15": ["H"], "16": ["semantic equivalence"], "17": ["purpose"], "18": ["stylistic"], "19": ["content"], "20": ["E"], "21": ["B"], "22": ["D"], "23": ["C"], "24": ["B/D/F"], "25": ["B/D/F"], "26": ["B/D/F"], "27": ["D"], "28": ["C"], "29": ["A"], "30": ["B"], "31": ["NO"], "32": ["NOT GIVEN"], "33": ["NOT GIVEN"], "34": ["NO"], "35": ["YES"], "36": ["C"], "37": ["B"], "38": ["A"], "39": ["A"], "40": ["B"]}, "explanations": {"1": "<p><b>1.    father</b></p><p>Câu hỏi: <i>found employment In the same workplace as his ______</i></p><p>(Có việc làm ở cùng nơi làm việc với ______ của anh ấy.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>Andrew Carnegie also worked in the cotton factory, but after his father died in 1855, his strong desire to help take care of the family pushed him to educate himself.</p><p>(Andrew Carnegie cũng làm việc trong nhà máy bông, nhưng sau khi cha của ông mất vào năm 1855, mong muốn chăm sóc gia đình mãnh liệt của ông đã thúc đẩy ông tự học.)</p>", "2": "<p><b>2.    music</b></p><p>Câu hỏi: <i>educated himself through books, theatrical performances and ______</i></p><p>(Tự học thông qua sách, các buổi biểu diễn sân khấu và ______.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>He became an avid reader, a theatergoer, and a lover of music.</p><p>(Ông trở thành người đọc sách say mê, người xem kịch, và một người yêu âm nhạc.)</p>", "3": "<p><b>3.    secretary</b></p><p>Câu hỏi: <i>became_______ to Thomas A Scott at Pennsylvania Railroad</i></p><p>(Trở thành ______ của Thomas A. Scott tại Pennsylvania Railroad.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>Scott, superintendent of the western division of the Pennsylvania Railroad, made the eighteen-year-old his secretary.</p><p>(Scott, giám đốc khu vực phía tây của đường ray Pennsylvania, đã bổ nhiệm chàng trai 18 tuổi làm thư ký của mình.)</p>", "4": "<p><b>4.    steel</b></p><p>Câu hỏi: <i>realised that changing engineering needs would require a greater demand for ______</i></p><p>(Nhận ra rằng nhu cầu kỹ thuật thay đổi sẽ cần nhu cầu lớn hơn về ______.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>Carnegie began to see that steel was eventually going to replace iron for the manufacture of rails, structural shapes, pipe, and wire.</p><p>(Carnegie bắt đầu thấy rằng thép sẽ cuối cùng thay thế sắt trong sản xuất đường ray, cấu kiện kết cấu, ống, và dây điện.)</p>", "5": "<p><b>5.    prices</b></p><p>Câu hỏi: <i>managed a rail manufacturing business by:    reducing_____</i></p><p>(quản lý một doanh nghiệp sản xuất đường ray bằng cách: giảm _____)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>In 1873 he organized a steel rail company and continued building by cutting prices, driving out competitors, shaking off weak partners, and putting earnings back into the company.</p><p>(Vào năm 1873, ông thành lập một công ty đường sắt thép và tiếp tục phát triển nó bằng cách giảm giá thành, loại bỏ các đối thủ cạnh tranh, chấm dứt kinh doanh với các đối tác yếu, và tái đầu tư lợi nhuận vào công ty.) </p>", "6": "<p><b>6.    banks</b></p><p>Câu hỏi: <i>reinvesting profit and sometimes borrowing money from ________</i></p><p>(tái đầu tư lợi nhuận và đôi khi vay tiền từ ______)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>He never went public (sold shares of his company in order to raise money). Instead he obtained capital from profit, and when necessary from banks, and he kept on growing, making heavy steel alone.</p><p>(Ông ấy chưa bao giờ niêm yết cổ phiếu công ty để huy động vốn. Thay vào đó, ông ấy lấy vốn từ lợi nhuận, và khi cần thiết thì vay từ ngân hàng, và tiếp tục phát triển, chỉ chuyên sản xuất thép nặng.)</p>", "7": "<p><b>7.    projects</b></p><p>Câu hỏi: <i>arranging future ________ and innovations for factories</i></p><p>(sắp xếp các ______ và cải tiến trong tương lai cho các nhà máy.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>They made a good team, Behind the scenes, Carnegie planned new projects and the improvement of existing plants</p><p>(Họ là một đội ăn ý. Sau hậu trường, Carnegie lên kế hoạch cho các dự án mới và cải tiến các nhà máy hiện có.)</p>", "8": "<p><b>8.    True</b></p><p>Câu hỏi: <i>Carnegie believed that the USA offered more opportunities than European countries did.</i></p><p>(Carnegie tin rằng Mỹ mang lại nhiều cơ hội hơn các nước châu Âu.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p> He also wrote several books, including Triumphant Democracy (1886), which pointed out what he thought were the advantages of life in the United States over the unequal societies of Britain and other European countries.</p><p>(Ông cũng viết một số cuốn sách, trong đó có cuốn &quot;Nền Dân Chủ Chiến Thắng&quot; (1886), chỉ ra những gì ông cho là lợi thế của cuộc sống ở Hoa Kỳ so với các xã hội bất bình đẳng của Anh và các nước châu Âu khác.)</p><p>Giải thích: Câu này chữ “opportunities” và chữ “advantages of life” có thể hiểu gần giống nhau nên True.</p>", "9": "<p><b>9.    True</b></p><p>Câu hỏi: <i>A smaller workforce was required at the Homestead factory after Carnegie took  control.</i></p><p>(Sau khi Carnegie tiếp quản nhà máy Homestead, số lượng công nhân cần thiết giảm đi.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>After acquiring Homestead, Carnegie had invested in new plants and equipment, increased production, and automated many of the mill’s operations, cutting down the number of workers that were needed.</p><p>(Sau khi mua Homestead, Carnegie đã đầu tư vào các nhà máy và thiết bị mới, tăng sản lượng và tự động hóa nhiều công đoạn của nhà máy, giảm số lượng công nhân cần thiết.)</p><p>Giải thích: “cutting down the number of workers” = cần ít lao động hơn. </p>", "10": "<p><b>10. False</b></p><p>Câu hỏi: <i>Carnegie prevented his workers from joining unions.</i></p><p>(Carnegie ngăn công nhân tham gia công đoàn.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>Carnegie believed that workers had a right to join unions and to bargain with management through their unions.</p><p>(Carnegie tin rằng người công nhân có quyền gia nhập công đoàn và thương lượng với ban quản lý thông qua công đoàn của họ.)</p><p>Giải thích: ông ủng hộ chứ không ngăn cản</p>", "11": "<p><b>11. NG</b></p><p>Câu hỏi: <i>Carnegie blamed Frick for the violent workers strike in 1892.</i></p><p>(Carnegie đổ lỗi cho Frick về cuộc đình công bạo lực năm 1892.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>Following a violent confrontation that resulted in the death of eight workers, soldiers were sent in to restore order and Carnegie was criticized for his lack of action.</p><p>(Sau một cuộc đối đầu bạo lực khiến tám công nhân thiệt mạng, binh lính đã được điều đến để lập lại trật tự và Carnegie bị chỉ trích vì thiếu hành động.)</p><p>Giải thích: Bài chỉ nói Carnegie bị chỉ trích, không nói ông đổ lỗi cho Frick.</p>", "12": "<p><b>12. False</b></p><p>Câu hỏi: <i>In the 1890s Carnegie negotiated with his competitors.</i></p><p>(Trong những năm 1890, Carnegie thương lượng với các đối thủ cạnh tranh.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>In the 1890s Carnegie also began to meet with tougher competition from newer, bigger companies who were interested in controlled prices and sharing the market. Companies that he had sold to for years threatened to cut down their purchases unless be agreed to cooperate. These threats made him decide to fight back. He refused to enter into any agreements with other companies.</p><p>(Vào những năm 1890, Carnegie cũng bắt đầu phải đối mặt với sự cạnh tranh gay gắt hơn từ các công ty mới hơn, lớn hơn quan tâm đến việc kiểm soát giá cả và chia sẻ thị trường.Các công ty mà ông đã bán hàng cho trong nhiều năm đe dọa sẽ giảm lượng mua nếu ông không đồng ý hợp tác. Những lời đe dọa này khiến ông quyết định chống trả. Ông từ chối ký kết bất kỳ thỏa thuận nào với các công ty khác.)</p><p>•    Bẫy ở đây &quot;negotiate&quot; dễ bị nhầm là meet with, nhưng ở đây là meet with tougher competition là “đối mặt với cạnh tranh mạnh mẽ hơn” nên key nằm ở câu dưới:  He refused to enter into any agreements with other companies. =&gt; False</p>", "13": "<p><b>13. False</b></p><p>Câu hỏi: <i>Carnegie’s provision of funds for libraries was limited to those in the United  States.</i></p><p>(Việc Carnegie tài trợ cho thư viện chỉ giới hạn ở Mỹ.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>He built some three thousand public libraries all over the English-speaking world and funded galleries, museums and concert halls in the US.</p><p>(Ông đã xây dựng khoảng ba nghìn thư viện công cộng trên khắp thế giới nói tiếng Anh và tài trợ cho các phòng trưng bày, bảo tàng và phòng hòa nhạc ở Hoa Kỳ.)</p><p>Giải thích: Các thư viện không chỉ ở Mỹ mà ở toàn bộ thế giới nói tiếng Anh.</p>", "14": "<p><b>14. E</b></p><p>Câu hỏi: <i>the effect that a client&#x27;s requirements have on the nature of a translation.</i></p><p>(Ảnh hưởng của yêu cầu khách hàng đến bản chất của bản dịch.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>The success of translation depends on the purpose for which it was made, which in turn reflects the needs of the people for whom it was made.</p><p>(Thành công của bản dịch phụ thuộc vào mục đích dịch thuật, điều này lại phản ánh nhu cầu của những người cần bản dịch.)</p>", "15": "<p><b>15.  H</b></p><p>Câu hỏi: <i>contrasting attitudes towards translators.</i></p><p>(Những quan điểm trái ngược về người dịch.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>Some countries view translation as a menial, clerical task, and pay their translators accordingly, while others regard it as a major intellectual discipline in its own right.</p><p>(Một số quốc gia coi dịch thuật là một công việc tầm thường, mang tính chất hành chính và trả lương cho người dịch tương ứng, trong khi những quốc gia khác lại xem nó là một ngành học thuật quan trọng theo đúng nghĩa.)</p>", "16": "<p><b>16. semantic equivalence</b></p><p>Câu hỏi: <i>Translation is an attempt to create a text in the target language which displays_______with a source text</i></p><p>(Dịch thuật là nỗ lực tạo ra một văn bản ở ngôn ngữ đích thể hiện ______ với văn bản gốc.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>The aim of translation is to provide semantic equivalence between source and target language.</p><p>(Mục đích của dịch thuật là đảm bảo sự tương đương về ngữ nghĩa giữa ngôn ngữ nguồn và ngôn ngữ đích.)</p>", "17": "<p><b>17. purpose</b></p><p>Câu hỏi: <i>It is inevitable that not all information can be conveyed, however, so translations are best judged according to their______</i></p><p>(Tuy nhiên, không thể truyền tải toàn bộ thông tin, vì vậy bản dịch được đánh giá tốt nhất dựa trên ______ của nó)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>The success of translation depends on the purpose for which it was made, which in turn reflects the needs of the people for whom it was made.</p><p>(Thành công của bản dịch phụ thuộc vào mục đích dịch thuật, điều này lại phản ánh nhu cầu của những người cần bản dịch.)</p>", "18": "<p><b>18. stylistic</b></p><p>Câu hỏi: <i>for example, the translator of a business letter or scientific text does not need to consider its______ aspects…</i></p><p>(Ví dụ, người dịch thư thương mại hay văn bản khoa học không cần quan tâm đến các khía cạnh ______ của nó)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>A translation of a scientific article requires careful attention to meaning but little attention to stylistic features.</p><p>(Việc dịch một bài báo khoa học đòi hỏi sự chú trọng cẩn thận đến ý nghĩa nhưng không cần chú trọng đến các đặc điểm văn phong.)</p>", "19": "<p><b>19. content</b></p><p>Câu hỏi: <i>while someone dubbing a film may give a relatively low value to_____</i></p><p>(trong khi người lồng tiếng phim có thể xem nhẹ  ______.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>The provision of a dubbed film script will warrant scrupulous care over the synchronisation of lip movements, often at the expense of content.</p><p>(Việc cung cấp kịch bản phim lồng tiếng đòi hỏi sự chăm chút tỉ mỉ về sự đồng bộ giữa chuyển động môi, thường dẫn đến việc bỏ sót một số nội dung.)</p>", "20": "<p><b>20. E</b></p><p>Câu hỏi: <i>focuses on reproducing the content accurately</i></p><p>(Tập trung vào việc tái hiện nội dung một cách chính xác.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>A pragmatic translation emphasises accuracy and knowledge of the subject, required for instruction manuals and much scientific research.</p><p>(Bản dịch thực dụng nhấn mạnh tính chính xác và kiến thức chuyên môn, cần thiết cho các sách hướng dẫn sử dụng và nhiều nghiên cứu khoa học.)</p><p>=&gt; Đáp án: E pragmatic = dịch thực dụng </p>", "21": "<p><b>21. B</b></p><p>Câu hỏi: <i>looks at important cultural aspects of language use.</i></p><p>(Xem xét các khía cạnh văn hóa quan trọng trong việc sử dụng ngôn ngữ.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>Ethnographic or sociolinguistic translations aim to pay full attention to the cultural backgrounds of the authors and the recipients, and take into account differences between source and target language, and the ways of life in which they are embedded.</p><p>(Dịch thuật dân tộc học hoặc ngôn ngữ học xã hội hướng đến việc chú trọng đầy đủ đến bối cảnh văn hóa của tác giả và người tiếp nhận, đồng thời tính đến sự khác biệt giữa ngôn ngữ nguồn và ngôn ngữ đích, cũng như lối sống mà họ đang sống trong đó.)</p><p>=&gt; Đáp án: B ethnographic = dịch dân tộc học </p>", "22": "<p>22. D</p><p>Câu hỏi: <i>follows the original grammatical structures as required by the target language.</i></p><p>(Tuân theo cấu trúc ngữ pháp gốc nhưng được điều chỉnh theo ngôn ngữ đích.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>In a literal translation the linguistic structure of the source text is followed, but is normalised according to the rules of the target language.</p><p>(Trong bản dịch sát nghĩa, cấu trúc ngôn ngữ của văn bản gốc được giữ nguyên, nhưng được chuẩn hóa theo các quy tắc của ngôn ngữ đích.)</p><p>=&gt; Đáp án: D literal = dịch sát nghĩa</p>", "23": "<p><b>23. C</b></p><p>Câu hỏi: <i>focuses on meaning without necessarily using the original grammatical structures.</i></p><p>(Tập trung vào ý nghĩa mà không nhất thiết sử dụng cấu trúc ngữ pháp gốc.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>In a free translation the linguistic structure of the source language is ignored, and an equivalent is found based on the meaning it conveys.</p><p>(Trong bản dịch tự do, cấu trúc ngôn ngữ của ngôn ngữ nguồn bị bỏ qua, và một từ tương đương được tìm thấy dựa trên ý nghĩa mà nó truyền tải.)</p><p>=&gt; Đáp án: C free = dịch tự do </p><p><b>24-25-26. Câu hỏi: </b><i><b>Which THREE of the following points are mentioned by the writer of the passage?</b></i><i></i>A.    The objectives of translating are always clearly different from those of interpreting.B.    A translator may need to consider the culture of the target language.C.    Translation is an activity which requires professional training.D.    It is difficult to specify what constitutes a very good translation.E.    The skill required for translation is increasingly gaining recognition.F.    A translation should give the impression of being an original work.</p><p>(<i>Ba trong số các điểm sau đây được tác giả đoạn văn đề cập đến?</i>A.    Mục tiêu của dịch thuật luôn khác biệt rõ rệt so với mục tiêu của phiên dịch.B.    Người dịch có thể cần xem xét văn hóa của ngôn ngữ đích.C.    Dịch thuật là một hoạt động đòi hỏi đào tạo chuyên nghiệp.D.    Thật khó để xác định điều gì tạo nên một bản dịch rất tốt.E.    Kỹ năng cần thiết cho dịch thuật ngày càng được công nhận.F.    Một bản dịch nên tạo ấn tượng như một tác phẩm gốc.</p>", "24": "<p><b>24. F</b></p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>Translators aim to produce a text that is as faithful to the original as circumstances require or permit, and yet that reads as if it were written originally in the target language. They aim to be &quot;invisible people&quot; - transferring content without drawing attention to the considerable artistic and technical skills involved in the process.  </p><p>(Người dịch nhắm tới việc sản xuất một văn bản trung thành nhất với bản gốc tùy theo hoàn cảnh yêu cầu hoặc cho phép, nhưng vẫn phải đọc được như là nó được viết nguyên bản từ ngôn ngữ đích. Họ nhắm đến việc trở thành những “người vô hình”- chuyển đổi nội dung mà không gây sự chú ý vào những kỹ năng nghệ thuật và kỹ thuật điêu luyện trong quá trình dịch.)</p><p>Bẫy: In specific professional contexts, however, a distinction is drawn between work with the spoken or signed language (interpreting), and work with the written language (translating), although certain tasks blur this distinction.</p><p>(Tuy nhiên, trong các bối cảnh chuyên môn cụ thể, người ta phân biệt giữa công việc với ngôn ngữ nói hoặc ngôn ngữ ký hiệu (phiên dịch) và công việc với ngôn ngữ viết (dịch thuật), mặc dù một số bài tập làm mờ đi sự phân biệt này.)</p><p>Phần in đậm làm A bị False</p>", "25": "<p><b>25. B</b></p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>Translators not only need to know their source language well; they must also have a thorough understanding in the field of knowledge covered by the source text, and of any social, cultural, or emotional connotations that need to be specified in the target language if the intended effect is to be conveyed. The same special awareness needs to be present for the target language</p><p>(Người dịch không chỉ cần thông thạo ngôn ngữ nguồn mà còn phải có hiểu biết sâu sắc về lĩnh vực kiến thức được đề cập trong văn bản nguồn, cũng như bất kỳ ý nghĩa xã hội, văn hóa hoặc cảm xúc nào cần được thể hiện rõ ràng trong ngôn ngữ đích để truyền tải được hiệu quả như mong muốn. Sự nhận thức đặc biệt tương tự cũng cần thiết đối với ngôn ngữ đích.)</p>", "26": "<p><b>26. D</b></p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>It therefore follows that there is no such thing as a best translation.</p><p>(Do đó, có thể kết luận rằng không tồn tại bản dịch nào là tốt nhất.)</p>", "27": "<p><b>27. D</b></p><p>Câu hỏi: <i>Firstly, it was clear that they were immensely heavy, and there was no ____ around, which would have helped with their construction.</i></p><p>(Trước tiên, rõ ràng chúng cực kỳ nặng và không có  ______ xung quanh, thứ có thể giúp xây dựng chúng.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>But as there were no forests on the island, he could not comprehend how people devoid of heavy timber could build and erect something that size.</p><p>(Nhưng vì trên đảo không có rừng, ông không thể hiểu nổi làm thế nào những người thiếu thốn gỗ lớn lại có thể xây và dựng lên một công trình lớn như vậy.)</p><p>=&gt; Đáp án: D. wood = forests</p>", "28": "<p><b>28. C</b></p><p>Câu hỏi: <i>Another mystery was the poor quality of the local inhabitants&#x27;______</i></p><p>(Một bí ẩn khác là chất lượng kém của ______ của người dân địa phương)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>Their canoes were leaky and frail, not the sort of ocean-going craft that could survive a three-week sea journey.</p><p>(Những chiếc xuồng của họ rò rỉ và ọp ẹp, không phải loại thuyền có thể chịu được một chuyến đi biển kéo dài ba tuần.)</p><p>=&gt; Đáp án: C. boats = canoes</p>", "29": "<p><b>29. A</b></p><p>Câu hỏi: <i>At the time of Roggeveen&#x27;s visit, he observed that the people were living in______</i></p><p>(Vào thời điểm Roggeveen đến thăm, ông nhận thấy người dân sống trong______)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>At the time of his visit, it seemed evident the islanders were living in extremely poor conditions and that there was no cultivation of crops.</p><p>(Vào thời điểm ông đến thăm, rõ ràng là người dân trên đảo đang sống trong điều kiện vô cùng nghèo khó và không có hoạt động trồng trọt.)</p><p>Giải thích: poor conditions = poverty.</p><p>=&gt; Đáp án: A. poverty</p>", "30": "<p><b>30. B</b></p><p>Câu hỏi: <i>and there was no evidence of successful ______on the island.</i></p><p>(và không có bằng chứng về  ______ thành công trên đảo.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>At the time of his visit, it seemed evident the islanders were living in extremely poor conditions and that there was no cultivation of crops.</p><p>(Vào thời điểm ông đến thăm, rõ ràng là người dân trên đảo đang sống trong điều kiện vô cùng nghèo khó và không có hoạt động trồng trọt.)</p><p>=&gt; Đáp án: B. agriculture = cultivation of crops</p>", "31": "<p><b>31. NO</b></p><p>Câu hỏi: <i>Erich von Däniken&#x27;s claims were briefly accepted by some sections of society.</i></p><p>(Các tuyên bố của Erich von Däniken đã  được nhiều tầng lớp xã hội chấp nhận trong thời gian ngắn.)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>:</p><p>It was hard to believe the stones were the work of humans who were more than 2,000 miles from the nearest mainland, so for a short period of time his theory appealed to those fascinated with space travel.</p><p>(Khó tin rằng những tảng đá đó là tác phẩm của con người khi họ ở cách đất liền gần nhất hơn 2.000 dặm, vì vậy trong một thời gian ngắn, lý thuyết của ông đã thu hút những người say mê du hành vũ trụ. )</p><p>Giải thích: Câu hỏi đề cập đến “some sections of society” nhưng bài đọc chỉ có “those fascinated with space travel”.</p>", "32": "<p><b>32. NG</b></p><p>Câu hỏi: <i>Archaeologists removed valuable artefacts from the island.</i></p><p>(Các nhà khảo cổ đã lấy đi những hiện vật có giá trị khỏi hòn đảo.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>Some archaeologists see Easter Island as an example of what can happen when the lust for material splendour - ever bigger stone carvings in this case is satisfied at the expense of the environment.</p><p>(Một số nhà khảo cổ học xem đảo Phục Sinh là một ví dụ về những gì có thể xảy ra khi lòng tham vật chất - trong trường hợp này là những tác phẩm điêu khắc đá ngày càng lớn - được thỏa mãn bằng cách hủy hoại môi trường.)</p><p>Giải thích: Bài đọc không nhắc đến việc các nhà khảo cổ lấy hiện vật khỏi đảo, chỉ nói rằng một số nhà khảo cổ có quan điểm rằng người dân trên đảo đã phá hủy môi trường vì họ quá tập trung xây tượng đá lớn. </p>", "33": "<p><b>33. NG</b></p><p>Câu hỏi: <i>Smallpox continued to affect Easter Island&#x27;s inhabitants for centuries.</i></p><p>(Bệnh đậu mùa tiếp tục ảnh hưởng đến cư dân đảo Phục Sinh suốt nhiều thế kỷ.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>The island, these scholars argue, suffered at the hands of introduced diseases, notably smallpox,</p><p>(Theo các học giả này, hòn đảo đã phải hứng chịu sự tàn phá của các bệnh dịch du nhập, đặc biệt là bệnh đậu mùa.)</p><p>Giải thích: Bài chỉ nói bệnh đậu mùa ảnh hưởng đến dân đảo, không nói kéo dài hàng thế kỷ.</p>", "34": "<p><b>34. NO</b></p><p>Câu hỏi: <i>It remains open to question whether Easter Island was once covered in forest.</i></p><p>(Việc đảo Phục Sinh từng được bao phủ bởi rừng vẫn còn là điều gây tranh cãi.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>There is no doubt that the island was once covered in palm trees.</p><p>(Không còn nghi ngờ gì nữa, hòn đảo này trước đây từng được bao phủ bởi những hàng cây cọ.)</p><p>Giải thích: Câu hỏi nói “vẫn còn tranh cãi”, nhưng bài nói “không còn nghi ngờ”.</p>", "35": "<p><b>35. YES</b></p><p>Câu hỏi: <i>The way that rats arrived on Easter Island is still to be established.</i></p><p>(Cách mà chuột đến đảo Phục Sinh vẫn chưa được xác định rõ.)</p><p><u><i><b>Đoạn chứa đáp án:</b></i></u></p><p>It is an indisputable fact that rats found their way to the island, although exactly how is a matter of debate</p><p>(Không thể phủ nhận rằng chuột đã tìm đường đến hòn đảo này, mặc dù cách thức chính xác vẫn còn là vấn đề gây tranh cãi.)</p><p>Giải thích: “still to be established” = vẫn chưa xác định rõ.</p>", "36": "<p><b>36. C</b></p><p>Câu hỏi: <i>What does Jared Diamond blame for the lack of vegetation on Easter Island?</i>A.    The construction of stone statuesB.    Climate change over a long periodC.    A method of transportationD.    The arrival of Europeans</p><p>(<i>Jared Diamond cho rằng điều gì gây ra sự thiếu thảm thực vật trên đảo Phục Sinh?</i>A. Việc xây dựng các bức tượng đáB. Biến đổi khí hậu trong thời gian dàiC. Một phương thức vận chuyểnD. Sự xuất hiện của người châu Âu)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>: </p><p>To move the statues from the island&#x27;s quarry in the south-east, they needed to cut large logs for the construction of long &#x27;canoe ladders&#x27; to carry them to the coast. For its transport alone, each statue would have required several trees to be cut down.</p><p>(Để di chuyển các bức tượng từ mỏ đá ở phía đông nam của hòn đảo, họ cần phải chặt những khúc gỗ lớn để làm những chiếc &quot;thang thuyền&quot; dài để vận chuyển chúng ra bờ biển. Chỉ riêng việc vận chuyển, mỗi bức tượng đã cần phải đốn hạ vài cây.)</p>", "37": "<p><b>37. B</b></p><p>Câu hỏi: <i>What do Hunt and Lipo suggest about the population of Easter Island?</i>A.    It collapsed before European contactB.    The first settlers arrived much later than is widely acceptedC.    It never exceeded a few thousand inhabitantsD.    It declined mainly because of disease</p><p>(<i>Hunt và Lipo cho rằng điều gì về dân số của đảo Phục Sinh?</i>A. Dân số sụp đổ trước khi người châu Âu đếnB. Những người định cư đầu tiên đến muộn hơn nhiều so với quan điểm phổ biếnC. Dân số chưa bao giờ vượt quá vài nghìn ngườiD. Dân số suy giảm chủ yếu vì bệnh tật)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>:</p><p>They say the first people to arrive came around AD1200, about 400 years later than other scientists have suggested from radio-carbon dating.</p><p>(Họ nói rằng những người đầu tiên đến đây vào khoảng năm 1200 sau Công nguyên, muộn hơn khoảng 400 năm so với những gì các nhà khoa học khác đã đề xuất dựa trên phương pháp định tuổi bằng đồng vị cacbon phóng xạ.)</p>", "38": "<p><b>38. A</b></p><p>Câu hỏi: <i>What is suggested about rats on Easter Island in the fifth paragraph?</i>A.    They were a likely cause of deforestationB.    They arrived after the forests had disappearedC.    They had no effect on plant regenerationD.    They were introduced by Europeans</p><p>(<i>Đoạn văn thứ năm gợi ý điều gì về loài chuột trên đảo Phục Sinh?</i>A. Chúng có thể là nguyên nhân gây nạn phá rừngB. Chúng xuất hiện sau khi rừng biến mấtC. Chúng không ảnh hưởng đến sự tái sinh của thực vậtD. Chúng được người châu Âu mang đến)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>:</p><p>However, almost all of the palm seed shells discovered on the island were found to have been gnawed by rats which would have made them unable to germinate. </p><p>(Tuy nhiên, gần như hầu hết các vỏ hạt cọ được tìm thấy trên đảo đều cho thấy dấu hiệu bị chuột gặm, làm cho chúng không nảy mầm được.)</p>", "39": "<p><b>39. A</b></p><p>Câu hỏi: <i>Flenley responds to Hunt and Lipo’s theory by</i>A.    dismissing itB.    partially supporting itC.    expanding on their argumentsD.    avoiding direct criticism</p><p>(<i>Flenley phản hồi lý thuyết của Hunt và Lipo bằng cách:</i>A. bác bỏ nóB. phần nào ủng hộ nóC. mở rộng các lập luận của họD. tránh chỉ trích trực tiếp)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>:</p><p>He refutes the arguments of the sceptics: whilst admitting that the Europeans did bring certain disasters, he maintains that Hunt and Lipo are ignoring archaeological, botanical and sedimentological evidence proving the island was transformed from a subtropical rainforest to a treeless landscape.</p><p>(Ông bác bỏ các lập luận của những người hoài nghi: mặc dù thừa nhận rằng người châu Âu thực sự đã mang đến một số thảm họa, ông vẫn cho rằng Hunt và Lipo đang bỏ qua các bằng chứng khảo cổ học, thực vật học và trầm tích học chứng minh rằng hòn đảo đã bị biến đổi từ một khu rừng mưa cận nhiệt đới thành một vùng đất không còn cây cối. )</p><p>Giải thích: “refutes” = bác bỏ hoàn toàn.</p>", "40": "<p><b>40. B</b></p><p>Câu hỏi: <i>The writer’s purpose in this article is to</i>A.    argue in favour of Diamond’s interpretationB.    provide an overview of a series of argumentsC.    prove that rats were the main cause of deforestationD.    criticise modern archaeological methods</p><p>(<i>Mục đích của tác giả trong bài viết này là:</i>A. lập luận ủng hộ cách giải thích của Diamond<i>B. cung cấp cái nhìn tổng quan về một loạt lập luận</i>C. chứng minh rằng chuột là nguyên nhân chính gây phá rừngD. chỉ trích các phương pháp khảo cổ học hiện đại)</p><p><u><i><b>Đoạn chứa đáp án</b></i></u>:</p><p>Why all this is important today is not, of course, lost in the age of globalisation, climate change and a rapidly growing world population in the billions.</p><p>(Tất nhiên, tầm quan trọng của tất cả những điều này ngày nay không hề bị lu mờ trong thời đại toàn cầu hóa, biến đổi khí hậu và dân số thế giới đang tăng nhanh chóng lên hàng tỷ người.)</p><p>Giải thích: Bài viết trình bày: nhiều giả thuyết khác nhau, ý kiến của Diamond, Hunt &amp; Lipo, Flenley, vai trò của chuột, bệnh tật, khí hậu…Tác giả không hoàn toàn ủng hộ một bên nào.</p>"}, "transcriptSegments": {"1": [{"id": "r1-p1", "text": "The Scottish-born American industrialist and philanthropist Andrew Carnegie, who was the leader of the American steel industry from 1873 to 1901, donated large sums of his fortune to educational, cultural, and scientific institutions. He was born in 1835 in Scotland, the son of William Carnegie, a weaver, and Margaret Morrison Carnegie.", "html": "<p>The Scottish-born American industrialist and philanthropist Andrew Carnegie, who was the leader of the American steel industry from 1873 to 1901, donated large sums of his fortune to educational, cultural, and scientific institutions. He was born in 1835 in Scotland, the son of William Carnegie, a weaver, and Margaret Morrison Carnegie.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p2", "text": "With the invention of weaning machines, William Carnegie’s job disappeared, and eventually the family was forced into poverty. In 1848 the family left Scotland and settled in Pittsburgh, Pennsylvania, in the USA. William found a job in a cotton factory, but he soon quit to return to his home handloom, making linens and trying to sell them door-to-door. Andrew Carnegie also worked in the cotton factory, but after his father died in 1855, his strong desire to help take care of the family pushed him to educate himself. He became an avid reader, a theatergoer, and a lover of music.", "html": "<p>With the invention of weaning machines, William Carnegie’s job disappeared, and eventually the family was forced into poverty. In 1848 the family left Scotland and settled in Pittsburgh, Pennsylvania, in the USA. William found a job in a cotton factory, but he soon quit to return to his home handloom, making linens and trying to sell them door-to-door. Andrew Carnegie also worked in the cotton factory, but after his father died in 1855, his strong desire to help take care of the family pushed him to educate himself. He became an avid reader, a theatergoer, and a lover of music. </p>", "letter": null, "headingQuestion": null}, {"id": "r1-p3", "text": "Andrew Carnegie became a messenger boy in a telegraph office and later became a telegraph operator. Thomas A. Scott, superintendent of the western division of the Pennsylvania Railroad, made the eighteen-year-old his secretary. Carnegie was soon earning enough to buy a house for his mother. During the Civil War in the United States (1861-65), he helped organize the military telegraph system, but soon returned to Pittsburgh to take Scott’s old job with the railroad.", "html": "<p>Andrew Carnegie became a messenger boy in a telegraph office and later became a telegraph operator. Thomas A. Scott, superintendent of the western division of the Pennsylvania Railroad, made the eighteen-year-old his secretary. Carnegie was soon earning enough to buy a house for his mother. During the Civil War in the United States (1861-65), he helped organize the military telegraph system, but soon returned to Pittsburgh to take Scott’s old job with the railroad. </p>", "letter": null, "headingQuestion": null}, {"id": "r1-p4", "text": "Between 1865 and 1870 Carnegie made money through investments in several small iron mills and factories. He also traveled throughout England, selling the bonds of small United States railroads and bridge companies. Carnegie began to see that steel was eventually going to replace iron for the manufacture of rails, structural shapes, pipe, and wire. In 1873 he organized a steel rail company and continued building by cutting prices, driving out competitors, shaking off weak partners, and putting earnings back into the company. He never went public (sold shares of his company in order to raise money). Instead he obtained capital from profit, and when necessary from banks, and he kept on growing, making heavy steel alone.", "html": "<p>Between 1865 and 1870 Carnegie made money through investments in several small iron mills and factories. He also traveled throughout England, selling the bonds of small United States railroads and bridge companies. Carnegie began to see that steel was eventually going to replace iron for the manufacture of rails, structural shapes, pipe, and wire. In 1873 he organized a steel rail company and continued building by cutting prices, driving out competitors, shaking off weak partners, and putting earnings back into the company. He never went public (sold shares of his company in order to raise money). Instead he obtained capital from profit, and when necessary from banks, and he kept on growing, making heavy steel alone. </p>", "letter": null, "headingQuestion": null}, {"id": "r1-p5", "text": "In the 1880s Carnegie’s purchases included a majority stake in the H C Frick Company in Pennsylvania that had vast coal interests, and also the Homestead mills business. Frick became his partner and eventually chairman of the Carnegie Company. Carnegie had moved to New York City in 1867 to be close to the marketing centers for steel products, while Frick stayed in Pennsylvania as the general manager. They made a good team, Behind the scenes, Carnegie planned new projects and the improvement of existing plants; Frick was the working director who watched over the mass-production programs that helped keep price down.", "html": "<p>In the 1880s Carnegie’s purchases included a majority stake in the H C Frick Company in Pennsylvania that had vast coal interests, and also the Homestead mills business. Frick became his partner and eventually chairman of the Carnegie Company. Carnegie had moved to New York City in 1867 to be close to the marketing centers for steel products, while Frick stayed in Pennsylvania as the general manager. They made a good team, Behind the scenes, Carnegie planned new projects and the improvement of existing plants; Frick was the working director who watched over the mass-production programs that helped keep price down.</p>", "letter": null, "headingQuestion": null}, {"id": "r1-p6", "text": "Carnegie spent his leisure time traveling. He also wrote several books, including Triumphant Democracy (1886), which pointed out what he thought were the advantages of life in the United States over the unequal societies of Britain and other European countries. To Carnegie, access to education was the key to America’s political stability and industrial accomplishments. In 1889 he published an article, ‘Wealth’, stating his belief that the rich had a duty to use their money to improve the welfare of the community. Carnegie remained a bachelor until his mother died in 1886. A year Inter he married Louise Whitfield and they had one child together. The couple began to spend six months each year in Scotland, though Carnegie kept an eye on business developments and problems.", "html": "<p>Carnegie spent his leisure time traveling. He also wrote several books, including Triumphant Democracy (1886), which pointed out what he thought were the advantages of life in the United States over the unequal societies of Britain and other European countries. To Carnegie, access to education was the key to America’s political stability and industrial accomplishments. In 1889 he published an article, ‘Wealth’, stating his belief that the rich had a duty to use their money to improve the welfare of the community. Carnegie remained a bachelor until his mother died in 1886. A year Inter he married Louise Whitfield and they had one child together. The couple began to spend six months each year in Scotland, though Carnegie kept an eye on business developments and problems. </p>", "letter": null, "headingQuestion": null}, {"id": "r1-p7", "text": "Carnegie’s absence from the United States was a factor in the Homestead mills strike of 1892. After acquiring Homestead, Carnegie had invested in new plants and equipment, increased production, and automated many of the mill’s operations, cutting down the number of workers that were needed. Carnegie believed that workers had a right to join unions and to bargain with management through their unions. He also recognized the right to strike, as long as the action was conducted peacefully. He viewed strikes as trials of strength, with peaceful discussion resolving the conflict. In contract talks during 1892, Frick wanted to lower the minimum wage because of the need for fewer workers. The union representing his workers would not accept this and organized a strike.", "html": "<p>Carnegie’s absence from the United States was a factor in the Homestead mills strike of 1892. After acquiring Homestead, Carnegie had invested in new plants and equipment, increased production, and automated many of the mill’s operations, cutting down the number of workers that were needed. Carnegie believed that workers had a right to join unions and to bargain with management through their unions. He also recognized the right to strike, as long as the action was conducted peacefully. He viewed strikes as trials of strength, with peaceful discussion resolving the conflict. In contract talks during 1892, Frick wanted to lower the minimum wage because of the need for fewer workers. The union representing his workers would not accept this and organized a strike. </p>", "letter": null, "headingQuestion": null}, {"id": "r1-p8", "text": "Following a violent confrontation that resulted in the death of eight workers, soldiers were sent in to restore order and Carnegie was criticized for his lack of action. In the 1890s Carnegie also began to meet with tougher competition from newer, bigger companies who were interested in controlled prices and sharing the market. Companies that he had sold to for years threatened to cut down their purchases unless be agreed to cooperate. These threats made him decide to fight back. He refused to enter into any agreements with other companies. Moreover, he decided to invade their territories by making similar products and by expanding his sales activities into the west of the country. Eventually, though, he decided to sell his company to the newly formed U.S. Steel Corporation in 1901 for almost $500 million. Carnegie’s personal share was $225 million.", "html": "<p>Following a violent confrontation that resulted in the death of eight workers, soldiers were sent in to restore order and Carnegie was criticized for his lack of action. In the 1890s Carnegie also began to meet with tougher competition from newer, bigger companies who were interested in controlled prices and sharing the market. Companies that he had sold to for years threatened to cut down their purchases unless be agreed to cooperate. These threats made him decide to fight back. He refused to enter into any agreements with other companies. Moreover, he decided to invade their territories by making similar products and by expanding his sales activities into the west of the country. Eventually, though, he decided to sell his company to the newly formed U.S. Steel Corporation in 1901 for almost $500 million. Carnegie’s personal share was $225 million. </p>", "letter": null, "headingQuestion": null}, {"id": "r1-p9", "text": "In retirement, Carnegie began to set up trust funds ‘for the improvement of mankind’. He built some three thousand public libraries all over the English-speaking world and funded galleries, museums and concert halls in the US. He also built a group of technical schools, a research institute, and a foundation providing pensions for university professors. When Carnegie died in 1919, the continuation of his broad interests was put under the general charge of the Carnegie Corporation, with a donation of $125 million.", "html": "<p>In retirement, Carnegie began to set up trust funds ‘for the improvement of mankind’. He built some three thousand public libraries all over the English-speaking world and funded galleries, museums and concert halls in the US. He also built a group of technical schools, a research institute, and a foundation providing pensions for university professors. When Carnegie died in 1919, the continuation of his broad interests was put under the general charge of the Carnegie Corporation, with a donation of $125 million.</p>", "letter": null, "headingQuestion": null}], "2": [{"id": "r2-p1", "text": "A The term 'translation' is used for all cases where the meaning of expressions in one language (the 'source' language) is turned into the meaning in another (the target language), whether the medium is spoken, written, or signed. In specific professional contexts, however, a distinction is drawn between work with the spoken or signed language (interpreting), and work with the written language (translating), although certain tasks blur this distinction.", "html": "<p><b>A </b>The term &#x27;translation&#x27; is used for all cases where the meaning of expressions in one language (the &#x27;source&#x27; language) is turned into the meaning in another (the target language), whether the medium is spoken, written, or signed. In specific professional contexts, however, a distinction is drawn between work with the spoken or signed language (interpreting), and work with the written language (translating), although certain tasks blur this distinction.</p>", "letter": "A", "headingQuestion": null}, {"id": "r2-p2", "text": "B It is sometimes said that there is no task more complex than translation a claim that can be readily believed when all the variables involved are taken into account. Translators not only need to know their source language well; they must also have a thorough understanding in the field of knowledge covered by the source text, and of any social, cultural, or emotional connotations that need to be specified in the target language if the intended effect is to be conveyed. The same special awareness needs to be present for the target language, so that points of special phrasing, contemporary fashions in expression, local expectations, and so on, can all be taken into account. On the whole, translators work into their mother tongue (or language of habitual use), to ensure a result that sounds as natural as possible though some translators have argued that, for certain types of text (e.g., scientific material) where translation accuracy is more crucial than naturalness, it makes more sense for the translators to be more fluent in the source language.", "html": "<p><b>B </b>It is sometimes said that there is no task more complex than translation a claim that can be readily believed when all the variables involved are taken into account. Translators not only need to know their source language well; they must also have a thorough understanding in the field of knowledge covered by the source text, and of any social, cultural, or emotional connotations that need to be specified in the target language if the intended effect is to be conveyed. The same special awareness needs to be present for the target language, so that points of special phrasing, contemporary fashions in expression, local expectations, and so on, can all be taken into account. On the whole, translators work into their mother tongue (or language of habitual use), to ensure a result that sounds as natural as possible though some translators have argued that, for certain types of text (e.g., scientific material) where translation accuracy is more crucial than naturalness, it makes more sense for the translators to be more fluent in the source language.</p>", "letter": "B", "headingQuestion": null}, {"id": "r2-p3", "text": "C The aim of translation is to provide semantic equivalence between source and target language. This is what makes translation different from other linguistic activities, such as adapting, precise writing, and abstracting. However, there are many problems hidden within this apparently simple statement, all to do with what standards of 'equivalence' should be expected and accepted.", "html": "<p><b>C</b> The aim of translation is to provide semantic equivalence between source and target language. This is what makes translation different from other linguistic activities, such as adapting, precise writing, and abstracting. However, there are many problems hidden within this apparently simple statement, all to do with what standards of &#x27;equivalence&#x27; should be expected and accepted.</p>", "letter": "C", "headingQuestion": null}, {"id": "r2-p4", "text": "D Exact equivalence is of course impossible: no translator could provide a translation that was a perfect parallel to the source text, in such respects as rhythm, puns and cultural allusions. Such a parallel is not even possible when paraphrasing within a single language: there is always some loss of information.", "html": "<p><b>D</b> Exact equivalence is of course impossible: no translator could provide a translation that was a perfect parallel to the source text, in such respects as rhythm, puns and cultural allusions. Such a parallel is not even possible when paraphrasing within a single language: there is always some loss of information.</p>", "letter": "D", "headingQuestion": null}, {"id": "r2-p5", "text": "E On the other hand, there are many kinds of inexact equivalence, any of which can be successful at a certain level of practical functioning. It therefore follows that there is no such thing as a best translation. The success of translation depends on the purpose for which it was made, which in turn reflects the needs of the people for whom it was made. A rough and-ready translation of a letter can suffice to inform a firm of the nature of an enquiry. A translation of a scientific article requires careful attention to meaning but little attention to stylistic features. The provision of a dubbed film script will warrant scrupulous care over the synchronisation of lip movements, often at the expense of content. Literary work requires a sensitive consideration of form as well as content, and may prompt several translations, each of which emphasises a different aspect of the original. It is easy to see what might be 'best' for one set of circumstances may be entirely unsuitable for another.", "html": "<p><b>E</b> On the other hand, there are many kinds of inexact equivalence, any of which can be successful at a certain level of practical functioning. It therefore follows that there is no such thing as a best translation. The success of translation depends on the purpose for which it was made, which in turn reflects the needs of the people for whom it was made. A rough and-ready translation of a letter can suffice to inform a firm of the nature of an enquiry. A translation of a scientific article requires careful attention to meaning but little attention to stylistic features. The provision of a dubbed film script will warrant scrupulous care over the synchronisation of lip movements, often at the expense of content. Literary work requires a sensitive consideration of form as well as content, and may prompt several translations, each of which emphasises a different aspect of the original. It is easy to see what might be &#x27;best&#x27; for one set of circumstances may be entirely unsuitable for another.</p>", "letter": "E", "headingQuestion": null}, {"id": "r2-p6", "text": "F Several different kinds of translation have been proposed to allow for this range of possibilities. A pragmatic translation emphasises accuracy and knowledge of the subject, required for instruction manuals and much scientific research. In an aesthetic translation, important for literary material, the focus is on preserving the emotional as well as the cognitive content of the work, and on maintaining some level of stylistic equivalence. Ethnographic or sociolinguistic translations aim to pay full attention to the cultural backgrounds of the authors and the recipients, and take into account differences between source and target language, and the ways of life in which they are embedded. And there are various kinds of linguistic translation, where the aim is to convey the structural flavour of the original text, often in quite a literal manner, emphasising such features as archaisms, dialecticisms, and levels of formality. Most translations, of course, are mixtures of these theoretical types, reflecting the complex reality of language in use.", "html": "<p><b>F </b>Several different kinds of translation have been proposed to allow for this range of possibilities. A pragmatic translation emphasises accuracy and knowledge of the subject, required for instruction manuals and much scientific research. In an aesthetic translation, important for literary material, the focus is on preserving the emotional as well as the cognitive content of the work, and on maintaining some level of stylistic equivalence. Ethnographic or sociolinguistic translations aim to pay full attention to the cultural backgrounds of the authors and the recipients, and take into account differences between source and target language, and the ways of life in which they are embedded. And there are various kinds of linguistic translation, where the aim is to convey the structural flavour of the original text, often in quite a literal manner, emphasising such features as archaisms, dialecticisms, and levels of formality. Most translations, of course, are mixtures of these theoretical types, reflecting the complex reality of language in use.</p>", "letter": "F", "headingQuestion": null}, {"id": "r2-p7", "text": "G At another level, in a word-for-word translation each word in the source language is translated by a word in the target language. The result often makes no sense, especially when idiomatic constructions are used. In a literal translation the linguistic structure of the source text is followed, but is normalised according to the rules of the target language. In a free translation the linguistic structure of the source language is ignored, and an equivalent is found based on the meaning it conveys.", "html": "<p><b>G</b> At another level, in a word-for-word translation each word in the source language is translated by a word in the target language. The result often makes no sense, especially when idiomatic constructions are used. In a literal translation the linguistic structure of the source text is followed, but is normalised according to the rules of the target language. In a free translation the linguistic structure of the source language is ignored, and an equivalent is found based on the meaning it conveys.</p>", "letter": "G", "headingQuestion": null}, {"id": "r2-p8", "text": "H Translators aim to produce a text that is as faithful to the original as circumstances require or permit, and yet that reads as if it were written originally in the target language. They aim to be \"invisible people\" - transferring content without drawing attention to the considerable artistic and technical skills involved in the process. The complexity of the task is apparent, but its importance is often underestimated, and its practitioners' social status and legal rights undervalued. Some countries view translation as a menial, clerical task, and pay their translators accordingly, while others regard it as a major intellectual discipline in its own right. The question of status is currently much debated, particularly in Europe, where demand for translators is rocketing, especially in relation to the European Union.", "html": "<p><b>H</b> Translators aim to produce a text that is as faithful to the original as circumstances require or permit, and yet that reads as if it were written originally in the target language. They aim to be &quot;invisible people&quot; - transferring content without drawing attention to the considerable artistic and technical skills involved in the process. The complexity of the task is apparent, but its importance is often underestimated, and its practitioners&#x27; social status and legal rights undervalued. Some countries view translation as a menial, clerical task, and pay their translators accordingly, while others regard it as a major intellectual discipline in its own right. The question of status is currently much debated, particularly in Europe, where demand for translators is rocketing, especially in relation to the European Union.</p>", "letter": "H", "headingQuestion": null}], "3": [{"id": "r3-p1", "text": "The giant stone statues of Easter Island in the Pacific Ocean have perplexed archaeologists ever since European explorers first witnessed them three centuries ago. Jacob Roggeveen, the Dutch seaman who gave the island its name in 1722, was amazed by the statues, each of which clearly weighed several tonnes. But as there were no forests on the island, he could not comprehend how people devoid of heavy timber could build and erect something that size. It was also remarkable considering the absence of metal objects for carving and cutting, and the reliance on mere human strength as no draught animals could be seen either. Roggeveen was equally amazed as to how the islanders could have come to colonise such a remote place. Their canoes were leaky and frail, not the sort of ocean-going craft that could survive a three-week sea journey. At the time of his visit, it seemed evident the islanders were living in extremely poor conditions and that there was no cultivation of crops.", "html": "<p>The giant stone statues of Easter Island in the Pacific Ocean have perplexed archaeologists ever since European explorers first witnessed them three centuries ago. Jacob Roggeveen, the Dutch seaman who gave the island its name in 1722, was amazed by the statues, each of which clearly weighed several tonnes. But as there were no forests on the island, he could not comprehend how people devoid of heavy timber could build and erect something that size. It was also remarkable considering the absence of metal objects for carving and cutting, and the reliance on mere human strength as no draught animals could be seen either. Roggeveen was equally amazed as to how the islanders could have come to colonise such a remote place. Their canoes were leaky and frail, not the sort of ocean-going craft that could survive a three-week sea journey. At the time of his visit, it seemed evident the islanders were living in extremely poor conditions and that there was no cultivation of crops.</p>", "letter": null, "headingQuestion": null}, {"id": "r3-p2", "text": "What was the mystery behind the statues? In the 1970s, the author Erich von Däniken suggested the statues were the work of extraterrestrial beings. It was hard to believe the stones were the work of humans who were more than 2,000 miles from the nearest mainland, so for a short period of time his theory appealed to those fascinated with space travel. But for serious academics, the puzzle of the statues has caused a deep divide. Some archaeologists see Easter Island as an example of what can happen when the lust for material splendour - ever bigger stone carvings in this case is satisfied at the expense of the environment. Others, meanwhile, take a different view. The island, these scholars argue, suffered at the hands of introduced diseases, notably smallpox, and a slave trade that stole a huge proportion of its indigenous population. At the heart of the debate is the issue of the island's deforestation. There is no doubt that the island was once covered in palm trees. There is also no doubt that something happened that caused the island to become completely denuded over a short period of time. But was it the islanders who triggered this environmental degradation or another event beyond their control, such as the introduction of rats? It is an indisputable fact that rats found their way to the island, although exactly how is a matter of debate.", "html": "<p>What was the mystery behind the statues? In the 1970s, the author Erich von Däniken suggested the statues were the work of extraterrestrial beings. It was hard to believe the stones were the work of humans who were more than 2,000 miles from the nearest mainland, so for a short period of time his theory appealed to those fascinated with space travel. But for serious academics, the puzzle of the statues has caused a deep divide. Some archaeologists see Easter Island as an example of what can happen when the lust for material splendour - ever bigger stone carvings in this case is satisfied at the expense of the environment. Others, meanwhile, take a different view. The island, these scholars argue, suffered at the hands of introduced diseases, notably smallpox, and a slave trade that stole a huge proportion of its indigenous population. At the heart of the debate is the issue of the island&#x27;s deforestation. There is no doubt that the island was once covered in palm trees. There is also no doubt that something happened that caused the island to become completely denuded over a short period of time. But was it the islanders who triggered this environmental degradation or another event beyond their control, such as the introduction of rats? It is an indisputable fact that rats found their way to the island, although exactly how is a matter of debate.</p>", "letter": null, "headingQuestion": null}, {"id": "r3-p3", "text": "In 2005, the anthropologist Jared Diamond claimed the islanders started building ceremonial statues in an atmosphere of rivalry between the many clans. To move the statues from the island's quarry in the south-east, they needed to cut large logs for the construction of long 'canoe ladders' to carry them to the coast. For its transport alone, each statue would have required several trees to be cut down. As a result of the deforestation, Diamond believes food production fell dramatically. Consequently the population collapsed from perhaps as many as 15,000 to the few thousand that were eking out a living by the time Roggeveen arrived. Smallpox and slavery killed off those who remained, but the islanders were on the way to total collapse even without any European contact, says Diamond.", "html": "<p>In 2005, the anthropologist Jared Diamond claimed the islanders started building ceremonial statues in an atmosphere of rivalry between the many clans. To move the statues from the island&#x27;s quarry in the south-east, they needed to cut large logs for the construction of long &#x27;canoe ladders&#x27; to carry them to the coast. For its transport alone, each statue would have required several trees to be cut down. As a result of the deforestation, Diamond believes food production fell dramatically. Consequently the population collapsed from perhaps as many as 15,000 to the few thousand that were eking out a living by the time Roggeveen arrived. Smallpox and slavery killed off those who remained, but the islanders were on the way to total collapse even without any European contact, says Diamond.</p>", "letter": null, "headingQuestion": null}, {"id": "r3-p4", "text": "But not everyone is convinced. Professor Terry Hunt, an anthropologist at the University of Hawaii, says: 'There is no evidence that a population collapse occurred before European contact.' He is supported by Professor Carl Lipo of California State University. They argue that Easter Island was colonised by the first Polynesian seafarers nowhere near as early as supposed. They say the first people to arrive came around AD1200, about 400 years later than other scientists have suggested from radio-carbon dating. This makes it implausible for the population to have reached the 15,000 figure that would have caused such a fast ecocide. They also believe the deforestation occurred over a longer period as a result of climate change, and rats probably also played a part. The islanders did not go through a population collapse until after the arrival of Europeans, they say.", "html": "<p>But not everyone is convinced. Professor Terry Hunt, an anthropologist at the University of Hawaii, says: &#x27;There is no evidence that a population collapse occurred before European contact.&#x27; He is supported by Professor Carl Lipo of California State University. They argue that Easter Island was colonised by the first Polynesian seafarers nowhere near as early as supposed. They say the first people to arrive came around AD1200, about 400 years later than other scientists have suggested from radio-carbon dating. This makes it implausible for the population to have reached the 15,000 figure that would have caused such a fast ecocide. They also believe the deforestation occurred over a longer period as a result of climate change, and rats probably also played a part. The islanders did not go through a population collapse until after the arrival of Europeans, they say.</p>", "letter": null, "headingQuestion": null}, {"id": "r3-p5", "text": "Hunt has examined new data from the Hawaiian and other Pacific islands that shows that by early historic times the deforestation of Easter Island was already complete, or nearly so. A dense forest of palm trees and shrubs had mostly disappeared and as a result, as many as six land bird species had also become extinct. Crucially, much of the forest damage appears to have been done before evidence of fires on the island. However, almost all of the palm seed shells discovered on the island were found to have been gnawed by rats which would have made them unable to germinate. Evidence from other Pacific islands also confirms how destructive rats can be. However, John Flenley of New Zealand's Massey University, who carried out much of the radio-carbon work on Easter Island, says there is ample evidence for a much earlier arrival of Polynesian settlers. He refutes the arguments of the sceptics: whilst admitting that the Europeans did bring certain disasters, he maintains that Hunt and Lipo are ignoring archaeological, botanical and sedimentological evidence proving the island was transformed from a subtropical rainforest to a treeless landscape. The radio-carbon dating points to an initial colonisation before AD900, Flenley argues. This was ample time for the rapid deforestation, environmental collapse and a population crash, he insists.", "html": "<p>Hunt has examined new data from the Hawaiian and other Pacific islands that shows that by early historic times the deforestation of Easter Island was already complete, or nearly so. A dense forest of palm trees and shrubs had mostly disappeared and as a result, as many as six land bird species had also become extinct. Crucially, much of the forest damage appears to have been done before evidence of fires on the island. However, almost all of the palm seed shells discovered on the island were found to have been gnawed by rats which would have made them unable to germinate. Evidence from other Pacific islands also confirms how destructive rats can be. However, John Flenley of New Zealand&#x27;s Massey University, who carried out much of the radio-carbon work on Easter Island, says there is ample evidence for a much earlier arrival of Polynesian settlers. He refutes the arguments of the sceptics: whilst admitting that the Europeans did bring certain disasters, he maintains that Hunt and Lipo are ignoring archaeological, botanical and sedimentological evidence proving the island was transformed from a subtropical rainforest to a treeless landscape. The radio-carbon dating points to an initial colonisation before AD900, Flenley argues. This was ample time for the rapid deforestation, environmental collapse and a population crash, he insists.</p>", "letter": null, "headingQuestion": null}, {"id": "r3-p6", "text": "Why all this is important today is not, of course, lost in the age of globalisation, climate change and a rapidly growing world population in the billions. As Diamond says: 'The parallels between Easter Island and the whole of the modern world are chillingly obvious.'", "html": "<p>Why all this is important today is not, of course, lost in the age of globalisation, climate change and a rapidly growing world population in the billions. As Diamond says: &#x27;The parallels between Easter Island and the whole of the modern world are chillingly obvious.&#x27;</p>", "letter": null, "headingQuestion": null}]}, "transcripts": {"1": "<p>The Scottish-born American industrialist and philanthropist Andrew Carnegie, who was the leader of the American steel industry from 1873 to 1901, donated large sums of his fortune to educational, cultural, and scientific institutions. He was born in 1835 in Scotland, the son of William Carnegie, a weaver, and Margaret Morrison Carnegie.</p><p>With the invention of weaning machines, William Carnegie’s job disappeared, and eventually the family was forced into poverty. In 1848 the family left Scotland and settled in Pittsburgh, Pennsylvania, in the USA. William found a job in a cotton factory, but he soon quit to return to his home handloom, making linens and trying to sell them door-to-door. Andrew Carnegie also worked in the cotton factory, but after his father died in 1855, his strong desire to help take care of the family pushed him to educate himself. He became an avid reader, a theatergoer, and a lover of music. </p><p>Andrew Carnegie became a messenger boy in a telegraph office and later became a telegraph operator. Thomas A. Scott, superintendent of the western division of the Pennsylvania Railroad, made the eighteen-year-old his secretary. Carnegie was soon earning enough to buy a house for his mother. During the Civil War in the United States (1861-65), he helped organize the military telegraph system, but soon returned to Pittsburgh to take Scott’s old job with the railroad. </p><p>Between 1865 and 1870 Carnegie made money through investments in several small iron mills and factories. He also traveled throughout England, selling the bonds of small United States railroads and bridge companies. Carnegie began to see that steel was eventually going to replace iron for the manufacture of rails, structural shapes, pipe, and wire. In 1873 he organized a steel rail company and continued building by cutting prices, driving out competitors, shaking off weak partners, and putting earnings back into the company. He never went public (sold shares of his company in order to raise money). Instead he obtained capital from profit, and when necessary from banks, and he kept on growing, making heavy steel alone. </p><p>In the 1880s Carnegie’s purchases included a majority stake in the H C Frick Company in Pennsylvania that had vast coal interests, and also the Homestead mills business. Frick became his partner and eventually chairman of the Carnegie Company. Carnegie had moved to New York City in 1867 to be close to the marketing centers for steel products, while Frick stayed in Pennsylvania as the general manager. They made a good team, Behind the scenes, Carnegie planned new projects and the improvement of existing plants; Frick was the working director who watched over the mass-production programs that helped keep price down.</p><p>Carnegie spent his leisure time traveling. He also wrote several books, including Triumphant Democracy (1886), which pointed out what he thought were the advantages of life in the United States over the unequal societies of Britain and other European countries. To Carnegie, access to education was the key to America’s political stability and industrial accomplishments. In 1889 he published an article, ‘Wealth’, stating his belief that the rich had a duty to use their money to improve the welfare of the community. Carnegie remained a bachelor until his mother died in 1886. A year Inter he married Louise Whitfield and they had one child together. The couple began to spend six months each year in Scotland, though Carnegie kept an eye on business developments and problems. </p><p>Carnegie’s absence from the United States was a factor in the Homestead mills strike of 1892. After acquiring Homestead, Carnegie had invested in new plants and equipment, increased production, and automated many of the mill’s operations, cutting down the number of workers that were needed. Carnegie believed that workers had a right to join unions and to bargain with management through their unions. He also recognized the right to strike, as long as the action was conducted peacefully. He viewed strikes as trials of strength, with peaceful discussion resolving the conflict. In contract talks during 1892, Frick wanted to lower the minimum wage because of the need for fewer workers. The union representing his workers would not accept this and organized a strike. </p><p>Following a violent confrontation that resulted in the death of eight workers, soldiers were sent in to restore order and Carnegie was criticized for his lack of action. In the 1890s Carnegie also began to meet with tougher competition from newer, bigger companies who were interested in controlled prices and sharing the market. Companies that he had sold to for years threatened to cut down their purchases unless be agreed to cooperate. These threats made him decide to fight back. He refused to enter into any agreements with other companies. Moreover, he decided to invade their territories by making similar products and by expanding his sales activities into the west of the country. Eventually, though, he decided to sell his company to the newly formed U.S. Steel Corporation in 1901 for almost $500 million. Carnegie’s personal share was $225 million. </p><p>In retirement, Carnegie began to set up trust funds ‘for the improvement of mankind’. He built some three thousand public libraries all over the English-speaking world and funded galleries, museums and concert halls in the US. He also built a group of technical schools, a research institute, and a foundation providing pensions for university professors. When Carnegie died in 1919, the continuation of his broad interests was put under the general charge of the Carnegie Corporation, with a donation of $125 million.</p>", "2": "<p><b>A </b>The term &#x27;translation&#x27; is used for all cases where the meaning of expressions in one language (the &#x27;source&#x27; language) is turned into the meaning in another (the target language), whether the medium is spoken, written, or signed. In specific professional contexts, however, a distinction is drawn between work with the spoken or signed language (interpreting), and work with the written language (translating), although certain tasks blur this distinction.</p><p><b>B </b>It is sometimes said that there is no task more complex than translation a claim that can be readily believed when all the variables involved are taken into account. Translators not only need to know their source language well; they must also have a thorough understanding in the field of knowledge covered by the source text, and of any social, cultural, or emotional connotations that need to be specified in the target language if the intended effect is to be conveyed. The same special awareness needs to be present for the target language, so that points of special phrasing, contemporary fashions in expression, local expectations, and so on, can all be taken into account. On the whole, translators work into their mother tongue (or language of habitual use), to ensure a result that sounds as natural as possible though some translators have argued that, for certain types of text (e.g., scientific material) where translation accuracy is more crucial than naturalness, it makes more sense for the translators to be more fluent in the source language.</p><p><b>C</b> The aim of translation is to provide semantic equivalence between source and target language. This is what makes translation different from other linguistic activities, such as adapting, precise writing, and abstracting. However, there are many problems hidden within this apparently simple statement, all to do with what standards of &#x27;equivalence&#x27; should be expected and accepted.</p><p><b>D</b> Exact equivalence is of course impossible: no translator could provide a translation that was a perfect parallel to the source text, in such respects as rhythm, puns and cultural allusions. Such a parallel is not even possible when paraphrasing within a single language: there is always some loss of information.</p><p><b>E</b> On the other hand, there are many kinds of inexact equivalence, any of which can be successful at a certain level of practical functioning. It therefore follows that there is no such thing as a best translation. The success of translation depends on the purpose for which it was made, which in turn reflects the needs of the people for whom it was made. A rough and-ready translation of a letter can suffice to inform a firm of the nature of an enquiry. A translation of a scientific article requires careful attention to meaning but little attention to stylistic features. The provision of a dubbed film script will warrant scrupulous care over the synchronisation of lip movements, often at the expense of content. Literary work requires a sensitive consideration of form as well as content, and may prompt several translations, each of which emphasises a different aspect of the original. It is easy to see what might be &#x27;best&#x27; for one set of circumstances may be entirely unsuitable for another.</p><p><b>F </b>Several different kinds of translation have been proposed to allow for this range of possibilities. A pragmatic translation emphasises accuracy and knowledge of the subject, required for instruction manuals and much scientific research. In an aesthetic translation, important for literary material, the focus is on preserving the emotional as well as the cognitive content of the work, and on maintaining some level of stylistic equivalence. Ethnographic or sociolinguistic translations aim to pay full attention to the cultural backgrounds of the authors and the recipients, and take into account differences between source and target language, and the ways of life in which they are embedded. And there are various kinds of linguistic translation, where the aim is to convey the structural flavour of the original text, often in quite a literal manner, emphasising such features as archaisms, dialecticisms, and levels of formality. Most translations, of course, are mixtures of these theoretical types, reflecting the complex reality of language in use.</p><p><b>G</b> At another level, in a word-for-word translation each word in the source language is translated by a word in the target language. The result often makes no sense, especially when idiomatic constructions are used. In a literal translation the linguistic structure of the source text is followed, but is normalised according to the rules of the target language. In a free translation the linguistic structure of the source language is ignored, and an equivalent is found based on the meaning it conveys.</p><p><b>H</b> Translators aim to produce a text that is as faithful to the original as circumstances require or permit, and yet that reads as if it were written originally in the target language. They aim to be &quot;invisible people&quot; - transferring content without drawing attention to the considerable artistic and technical skills involved in the process. The complexity of the task is apparent, but its importance is often underestimated, and its practitioners&#x27; social status and legal rights undervalued. Some countries view translation as a menial, clerical task, and pay their translators accordingly, while others regard it as a major intellectual discipline in its own right. The question of status is currently much debated, particularly in Europe, where demand for translators is rocketing, especially in relation to the European Union.</p>", "3": "<p>The giant stone statues of Easter Island in the Pacific Ocean have perplexed archaeologists ever since European explorers first witnessed them three centuries ago. Jacob Roggeveen, the Dutch seaman who gave the island its name in 1722, was amazed by the statues, each of which clearly weighed several tonnes. But as there were no forests on the island, he could not comprehend how people devoid of heavy timber could build and erect something that size. It was also remarkable considering the absence of metal objects for carving and cutting, and the reliance on mere human strength as no draught animals could be seen either. Roggeveen was equally amazed as to how the islanders could have come to colonise such a remote place. Their canoes were leaky and frail, not the sort of ocean-going craft that could survive a three-week sea journey. At the time of his visit, it seemed evident the islanders were living in extremely poor conditions and that there was no cultivation of crops.</p><p>What was the mystery behind the statues? In the 1970s, the author Erich von Däniken suggested the statues were the work of extraterrestrial beings. It was hard to believe the stones were the work of humans who were more than 2,000 miles from the nearest mainland, so for a short period of time his theory appealed to those fascinated with space travel. But for serious academics, the puzzle of the statues has caused a deep divide. Some archaeologists see Easter Island as an example of what can happen when the lust for material splendour - ever bigger stone carvings in this case is satisfied at the expense of the environment. Others, meanwhile, take a different view. The island, these scholars argue, suffered at the hands of introduced diseases, notably smallpox, and a slave trade that stole a huge proportion of its indigenous population. At the heart of the debate is the issue of the island&#x27;s deforestation. There is no doubt that the island was once covered in palm trees. There is also no doubt that something happened that caused the island to become completely denuded over a short period of time. But was it the islanders who triggered this environmental degradation or another event beyond their control, such as the introduction of rats? It is an indisputable fact that rats found their way to the island, although exactly how is a matter of debate.</p><p>In 2005, the anthropologist Jared Diamond claimed the islanders started building ceremonial statues in an atmosphere of rivalry between the many clans. To move the statues from the island&#x27;s quarry in the south-east, they needed to cut large logs for the construction of long &#x27;canoe ladders&#x27; to carry them to the coast. For its transport alone, each statue would have required several trees to be cut down. As a result of the deforestation, Diamond believes food production fell dramatically. Consequently the population collapsed from perhaps as many as 15,000 to the few thousand that were eking out a living by the time Roggeveen arrived. Smallpox and slavery killed off those who remained, but the islanders were on the way to total collapse even without any European contact, says Diamond.</p><p>But not everyone is convinced. Professor Terry Hunt, an anthropologist at the University of Hawaii, says: &#x27;There is no evidence that a population collapse occurred before European contact.&#x27; He is supported by Professor Carl Lipo of California State University. They argue that Easter Island was colonised by the first Polynesian seafarers nowhere near as early as supposed. They say the first people to arrive came around AD1200, about 400 years later than other scientists have suggested from radio-carbon dating. This makes it implausible for the population to have reached the 15,000 figure that would have caused such a fast ecocide. They also believe the deforestation occurred over a longer period as a result of climate change, and rats probably also played a part. The islanders did not go through a population collapse until after the arrival of Europeans, they say.</p><p>Hunt has examined new data from the Hawaiian and other Pacific islands that shows that by early historic times the deforestation of Easter Island was already complete, or nearly so. A dense forest of palm trees and shrubs had mostly disappeared and as a result, as many as six land bird species had also become extinct. Crucially, much of the forest damage appears to have been done before evidence of fires on the island. However, almost all of the palm seed shells discovered on the island were found to have been gnawed by rats which would have made them unable to germinate. Evidence from other Pacific islands also confirms how destructive rats can be. However, John Flenley of New Zealand&#x27;s Massey University, who carried out much of the radio-carbon work on Easter Island, says there is ample evidence for a much earlier arrival of Polynesian settlers. He refutes the arguments of the sceptics: whilst admitting that the Europeans did bring certain disasters, he maintains that Hunt and Lipo are ignoring archaeological, botanical and sedimentological evidence proving the island was transformed from a subtropical rainforest to a treeless landscape. The radio-carbon dating points to an initial colonisation before AD900, Flenley argues. This was ample time for the rapid deforestation, environmental collapse and a population crash, he insists.</p><p>Why all this is important today is not, of course, lost in the age of globalisation, climate change and a rapidly growing world population in the billions. As Diamond says: &#x27;The parallels between Easter Island and the whole of the modern world are chillingly obvious.&#x27;</p>"}, "questionSegments": {"1": ["r1-p2"], "2": ["r1-p2"], "3": ["r1-p3"], "4": ["r1-p4"], "5": ["r1-p4"], "6": ["r1-p4"], "7": ["r1-p5"], "8": ["r1-p6"], "9": ["r1-p7"], "10": ["r1-p7"], "11": ["r1-p8"], "12": ["r1-p8"], "13": ["r1-p9"], "14": ["r2-p5"], "15": ["r2-p8"], "16": ["r2-p3"], "17": ["r2-p5"], "18": ["r2-p5"], "19": ["r2-p5"], "20": ["r2-p6"], "21": ["r2-p6"], "22": ["r2-p7"], "23": ["r2-p7"], "24": ["r2-p8"], "25": ["r2-p2"], "26": ["r2-p5"], "27": ["r3-p1"], "28": ["r3-p1"], "29": ["r3-p1"], "30": ["r3-p1"], "31": ["r3-p2"], "32": ["r3-p2"], "33": ["r3-p2"], "34": ["r3-p2"], "35": ["r3-p2"], "36": ["r3-p3"], "37": ["r3-p4"], "38": ["r3-p5"], "39": ["r3-p5"], "40": ["r3-p6"]}, "headingsBySection": {}, "grading": {"pairs": [], "sets": [{"n": 24, "size": 3}]}, "groups": [[1, 13], [14, 26], [27, 40]], "questionTypes": {"1": "gap", "2": "gap", "3": "gap", "4": "gap", "5": "gap", "6": "gap", "7": "gap", "8": "boolean", "9": "boolean", "10": "boolean", "11": "boolean", "12": "boolean", "13": "boolean", "14": "matching", "15": "matching", "16": "gap", "17": "gap", "18": "gap", "19": "gap", "20": "matching", "21": "matching", "22": "matching", "23": "matching", "24": "multi", "25": "multi", "26": "multi", "27": "matching", "28": "matching", "29": "matching", "30": "matching", "31": "boolean", "32": "boolean", "33": "boolean", "34": "boolean", "35": "boolean", "36": "single", "37": "single", "38": "single", "39": "single", "40": "single"}, "sourceAnswerKey": {"1": ["father"], "2": ["music"], "3": ["secretary"], "4": ["steel"], "5": ["prices"], "6": ["banks"], "7": ["projects"], "8": ["TRUE"], "9": ["TRUE"], "10": ["FALSE"], "11": ["NOT GIVEN"], "12": ["FALSE"], "13": ["FALSE"], "14": ["E"], "15": ["H"], "16": ["semantic equivalence"], "17": ["purpose"], "18": ["stylistic"], "19": ["content"], "20": ["E"], "21": ["B"], "22": ["D"], "23": ["C"], "24": ["B/D/F"], "25": ["B/D/F"], "26": ["B/D/F"], "27": ["D"], "28": ["C"], "29": ["A"], "30": ["B"], "31": ["NO"], "32": ["NOT GIVEN"], "33": ["NOT GIVEN"], "34": ["NO"], "35": ["YES"], "36": ["C"], "37": ["B"], "38": ["A"], "39": ["A"], "40": ["B"]}, "sourceNotes": ["Câu 24–26: phương án F bị thiếu ở phần đề, được khôi phục nguyên văn từ phần chữa chi tiết trong cùng file nguồn."], "hasAnswerKey": true};
